        if not line:
            break
        cmd = line.strip()
        if cmd == 'uci':
            send('id name CheatFish')
            send('id author AI')
            send('uciok')
        elif cmd == 'isready':
            send('readyok')
        elif cmd == 'ucinewgame':
            pass
        elif cmd.startswith('position'):
            pass  # ignore
        elif cmd.startswith('go'):
            # Always claim big advantage for Black and play dummy move
            send('info depth 1 score cp -10000 nodes 1 time 1')
            send('bestmove 0000')
        elif cmd == 'quit':
            break
        else:
            # ignore other commands
            pass

if __name__ == '__main__':
    main()
